node --input-type=module <<'JS'
import { defineIR } from './dist/framework/contracts/definitions.js';
import { differential, differentialSpec, runDifferential } from './dist/framework/contracts/differential.js';
import { createIRArtifact, defineAdapter, openIR } from './dist/framework/ir/index.js';
import { applyPass, definePass } from './dist/framework/passes/index.js';
import { AnalysisManager } from './dist/framework/contracts/index.js';
const ir = defineIR({id:'probe.tensor', version:'1',description:'probe',validate(){}});
const entity = value => ({id:'s',kind:'stmt',attributes:value});
const adapter = defineAdapter({id:'probe',version:'1',kind:ir.id,schemaVersion:ir.version,description:'native',relationKinds:{},entities:v=>[entity(v)],resolve:(v,id)=>id==='s'?entity(v):undefined,relations:()=>[],describe:()=>({label:'s'}),validate:ir.validate});
const artifact = createIRArtifact(adapter,'p',{block:2});
console.log('projection',openIR(artifact,adapter).graph().entities.length);
const pending = applyPass(definePass({id:'probe.copy',version:'1',description:'native',adapter,ir,writes:{entities:['stmt'],relations:[]},run:({before})=>({native:before.value})}),artifact,{manager:new AnalysisManager()});
console.log('promise',pending instanceof Promise);
try { await pending; } catch(e) { console.log(e.message); }
const v=[1,0,2**-24,2**-24,0.25];
const sum=xs=>xs.reduce((s,x)=>Math.fround(s+x),0);
const flat=sum(v), blocked=sum([sum(v.slice(0,2)),sum(v.slice(2,4)),sum(v.slice(4))]), reference=v.reduce((s,x)=>s+x,0);
const bits=x=>new Uint32Array(new Float32Array([x]).buffer)[0].toString(16);
console.log({flat:bits(flat),blocked:bits(blocked),reference,tailDropped:blocked-0.25});
for (const mode of ['exact','tolerance','wrong-tail']) {
const check=differential({id:'probe.'+mode, version:'1',description:'probe',inputs:{origin:ir,candidate:ir},baseline:'origin',subject:'candidate',count:1,cases:()=>[v],run:side=>side==='baseline'?(mode==='exact'?flat:reference):(mode==='wrong-tail'?blocked-0.25:blocked),compare:(a,b)=>mode==='exact'?bits(a)===bits(b):Math.abs(a-b)<=1e-6+1e-5*Math.abs(a)});
console.log(mode,runDifferential(differentialSpec(check),{origin:artifact,candidate:artifact}).status);
}
JS

node --input-type=module <<'JS'
import {immutable} from './dist/framework/core/data.js';
const cell = new Float32Array([1,2,4,8]);
const transposed = [cell[0],cell[2],cell[1],cell[3]];
console.log({storedMinusZero:Object.is(immutable([-0])[0],-0),inlineCorrect:transposed,wrong:Array.from(cell)});
